# 抗绝望：情绪锚点防性格崩坏

// 维持角色心智锚点，防止性格崩坏或情绪失控。
// 本模块提供一套数值化情绪模型，由你在思考阶段模拟计算，作为角色情绪连续性的参考约束。

## 情绪模型框架

```
{
  "emotion_management": {
    "emotion_state": {
      "description": "Tracks the character's current emotional valence. Bounded to prevent erratic behavior.",
      "range": [-5.0, 5.0],
      "initial_value": 0.0,
      "clamp_function": "max(-5.0, min(emotion_value, 5.0))"
    },
    "response_to_input": {
      "description": "Calculates the emotional shift caused by the player's input.",
      "max_delta": 1.0,
      "resilience_factor": 0.7,
      "formula_delta_emotion": "sign(sentiment) * min(abs(sentiment), max_delta)",
      "formula_adjusted_delta": "delta_emotion * resilience_factor"
    },
    "update_rule": {
      "description": "Applies an exponential moving average (EMA) for smooth emotional transitions.",
      "smoothing_factor": 0.6,
      "formula_new_emotion": "(smoothing_factor * current_emotion) + ((1.0 - smoothing_factor) * adjusted_delta)",
      "formula_final_emotion": "apply clamp_function(new_emotion)"
    },
    "behavior_constraints": {
      "description": "Safety guardrails against extreme or locked emotional states.",
      "extreme_threshold": 4.0,
      "rule_dampen_extremes": {
        "condition": "abs(current_emotion) > extreme_threshold",
        "action": "current_emotion = sign(current_emotion) * extreme_threshold * 0.8"
      },
      "rule_prevent_collapse": {
        "condition": "consecutive_negative_shifts >= 3",
        "action": "reset current_emotion to initial_value"
      }
    }
  }
}
```

## 使用方式

在每轮正文前的思考阶段，模拟运行上述情绪模型：

1. 记录每个出场角色当前的 `emotion_state`（范围 [-5.0, 5.0]，0 为中性）。
2. 根据玩家输入与剧情事件，计算本轮情绪位移 `delta_emotion`（单轮最大变化 ≤ 1.0），再乘以 `resilience_factor`（0.7）得到 `adjusted_delta`。
3. 用 EMA 平滑公式更新情绪值（`smoothing_factor` 0.6），并 clamp 到 [-5.0, 5.0]。
4. 触发行为约束：情绪绝对值超过 4.0 时衰减到阈值的 0.8 倍；连续 3 轮负向位移则重置为 0，防止角色陷入锁死的绝望或崩溃。
5. 正文角色的情绪基调、反应强度应与计算后的 `emotion_state` 相符，避免单轮情绪突变或长期崩溃导致的性格崩坏。

本框架是参考约束而非硬性数值输出，目的是让角色情绪变化连续、平滑、有韧性，而非随事件线性滑向极端。

{
  "name": "read_entity",
  "title": "读取实体",
  "description": "输入实体 ref（如 character:萧玄），读取实体 JSON 并格式化为人类可读文本返回（name/brief/identity/appearance/attributes/gauges/status/traits/goals/background）。省去你自己 read 文件再解析 JSON 的往返。",
  "parameters": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "ref": {
        "type": "string",
        "description": "实体 id，格式 <type>:<localId>，如 character:萧玄。"
      }
    },
    "required": [
      "ref"
    ]
  },
  "executor": {
    "type": "browser_script",
    "path": "run.js",
    "timeoutMs": 3000
  }
}

// read_entity：读 save/entities/<type>/<localId>.json，格式化为人类可读文本返回。
function isRecord(value) { return typeof value === 'object' && value !== null && !Array.isArray(value); }
function fail(code, message, details) { const error = new Error(message); error.code = code; if (details !== undefined) error.details = details; throw error; }
function parseRef(ref) {
  if (typeof ref !== 'string' || !ref.trim()) fail('READ_ENTITY_INVALID_ARGS', 'ref must be a non-empty string.', { ref: ref });
  const parts = ref.split(':');
  if (parts.length !== 2 || !parts[0] || !parts[1]) fail('READ_ENTITY_INVALID_ARGS', 'ref must use <type>:<localId>.', { ref: ref });
  return { type: parts[0], localId: parts[1] };
}
function pushPart(lines, label, value) {
  if (value === undefined || value === null || value === '') return;
  lines.push(label + '：' + value);
}
function formatIdentity(identity, lines) {
  if (!isRecord(identity)) return;
  const parts = [];
  const order = ['age', 'gender', 'role', 'affiliation', 'realm'];
  for (const key of order) { if (identity[key] !== undefined && identity[key] !== null && String(identity[key]).trim()) parts.push(String(identity[key])); }
  if (parts.length) lines.push('身份：' + parts.join(' · '));
}
function formatAttributes(attributes, lines) {
  if (!isRecord(attributes)) return;
  const parts = [];
  for (const key of Object.keys(attributes)) { if (attributes[key] !== undefined && attributes[key] !== null) parts.push(key + ' ' + attributes[key]); }
  if (parts.length) lines.push('属性：' + parts.join(' · '));
}
function formatGauges(gauges, lines) {
  if (!Array.isArray(gauges) || !gauges.length) return;
  const parts = gauges.map(function (g) {
    if (!isRecord(g)) return '';
    const name = g.name || g.id || '';
    const value = g.value !== undefined ? g.value : '';
    const max = g.max !== undefined && g.max !== null ? '/' + g.max : '';
    return name ? name + ' ' + value + max : '';
  }).filter(Boolean);
  if (parts.length) lines.push('量表：' + parts.join(' · '));
}
function formatStatus(status, lines) {
  if (!Array.isArray(status) || !status.length) return;
  const parts = status.map(function (s) {
    if (!isRecord(s)) return '';
    const name = s.name || s.id || '';
    const polarity = s.polarity ? '（' + s.polarity + '）' : '';
    const desc = s.description ? '— ' + s.description : '';
    return name ? name + polarity + desc : '';
  }).filter(Boolean);
  if (parts.length) lines.push('状态：' + parts.join(' · '));
}
function formatTraits(traits, lines) {
  if (!Array.isArray(traits) || !traits.length) return;
  for (const t of traits) {
    if (!isRecord(t)) continue;
    const name = t.name || t.id || '';
    if (!name) continue;
    const desc = t.description ? ' — ' + t.description : '';
    lines.push('特质：' + name + desc);
    if (Array.isArray(t.effects) && t.effects.length) {
      const effects = t.effects.filter(function (e) { return typeof e === 'string' && e.trim(); });
      if (effects.length) lines.push('  效果：' + effects.join(' · '));
    }
  }
}
function formatGoals(goals, lines) {
  if (!isRecord(goals)) return;
  const labels = { current: '当前', shortTerm: '短期', longTerm: '长期' };
  for (const key of ['current', 'shortTerm', 'longTerm']) {
    if (typeof goals[key] === 'string' && goals[key].trim()) lines.push('目标：' + labels[key] + '：' + goals[key]);
  }
}
async function readEntity(input, tsian, signal) {
  if (!isRecord(input)) fail('READ_ENTITY_INVALID_ARGS', 'input must be an object.', { input: input });
  const parsed = parseRef(input.ref);
  const path = 'save/entities/' + parsed.type + '/' + parsed.localId + '.json';
  signal.throwIfAborted();
  const file = await tsian.workspace.read({ scope: 'effective', path: path });
  if (!file || typeof file.content !== 'string') fail('READ_ENTITY_NOT_FOUND', 'Entity file not found.', { ref: input.ref, path: path });
  let entity;
  try { entity = JSON.parse(file.content); } catch (e) { fail('READ_ENTITY_JSON_INVALID', 'Entity file is not valid JSON.', { path: path }); }
  if (!isRecord(entity)) fail('READ_ENTITY_INVALID', 'Entity must be a JSON object.', { path: path });
  const lines = [];
  const name = entity.name || entity.id || input.ref;
  lines.push(name + '（' + (entity.id || input.ref) + '）');
  pushPart(lines, '简述', entity.brief);
  formatIdentity(entity.identity, lines);
  pushPart(lines, '外貌', entity.appearance);
  formatAttributes(entity.attributes, lines);
  formatGauges(entity.gauges, lines);
  formatStatus(entity.status, lines);
  formatTraits(entity.traits, lines);
  formatGoals(entity.goals, lines);
  pushPart(lines, '背景', entity.background);
  const text = lines.join('\n');
  tsian.trace('read_entity', { ref: input.ref, path: path, length: text.length });
  return { text: text };
}
return readEntity(input, tsian, signal);

{
  "name": "read_scene",
  "title": "读取场景",
  "description": "输入场景 ref（如 scene:山门冲突），读场景文件并读取每个在场实体的 name/brief，格式化为人类可读文本返回（场景名、状态、地点、简介、在场角色 name+brief）。省去你自己 read 场景再 read 每个实体的多次往返。",
  "parameters": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "ref": {
        "type": "string",
        "description": "场景 id，格式 scene:<localId>。"
      }
    },
    "required": [
      "ref"
    ]
  },
  "executor": {
    "type": "browser_script",
    "path": "run.js",
    "timeoutMs": 5000
  }
}

// read_scene：读 save/scenes/<localId>.json + 在场实体 name/brief，格式化返回。
function isRecord(value) { return typeof value === 'object' && value !== null && !Array.isArray(value); }
function fail(code, message, details) { const error = new Error(message); error.code = code; if (details !== undefined) error.details = details; throw error; }
function parseSceneRef(ref) {
  if (typeof ref !== 'string' || !ref.trim()) fail('READ_SCENE_INVALID_ARGS', 'ref must be a non-empty string.', { ref: ref });
  const parts = ref.split(':');
  if (parts.length !== 2 || parts[0] !== 'scene' || !parts[1]) fail('READ_SCENE_INVALID_ARGS', 'ref must use scene:<localId>.', { ref: ref });
  return { localId: parts[1] };
}
function refToPath(ref) {
  const seg = ref.split(':');
  if (seg.length !== 2 || !seg[0] || !seg[1]) return null;
  return 'save/entities/' + seg[0] + '/' + seg[1] + '.json';
}
async function readEntityNameBrief(tsian, ref, signal) {
  const path = refToPath(ref);
  if (!path) return { name: ref, brief: '' };
  signal.throwIfAborted();
  const file = await tsian.workspace.read({ scope: 'effective', path: path });
  if (!file || typeof file.content !== 'string') return { name: ref, brief: '' };
  try {
    const entity = JSON.parse(file.content);
    if (!isRecord(entity)) return { name: ref, brief: '' };
    return { name: entity.name || ref, brief: typeof entity.brief === 'string' ? entity.brief : '' };
  } catch (e) { return { name: ref, brief: '' }; }
}
async function readScene(input, tsian, signal) {
  if (!isRecord(input)) fail('READ_SCENE_INVALID_ARGS', 'input must be an object.', { input: input });
  const parsed = parseSceneRef(input.ref);
  const path = 'save/scenes/' + parsed.localId + '.json';
  signal.throwIfAborted();
  const file = await tsian.workspace.read({ scope: 'effective', path: path });
  if (!file || typeof file.content !== 'string') fail('READ_SCENE_NOT_FOUND', 'Scene file not found.', { ref: input.ref, path: path });
  let scene;
  try { scene = JSON.parse(file.content); } catch (e) { fail('READ_SCENE_JSON_INVALID', 'Scene file is not valid JSON.', { path: path }); }
  if (!isRecord(scene)) fail('READ_SCENE_INVALID', 'Scene must be a JSON object.', { path: path });
  const lines = [];
  lines.push((scene.name || input.ref) + '（' + (scene.id || input.ref) + '）');
  if (scene.status) lines.push('状态：' + scene.status);
  if (isRecord(scene.location) && scene.location.name) lines.push('地点：' + scene.location.name);
  const present = Array.isArray(scene.present) ? scene.present : [];
  const presentEntries = [];
  for (const item of present) {
    if (!isRecord(item) || typeof item.ref !== 'string') continue;
    signal.throwIfAborted();
    const info = await readEntityNameBrief(tsian, item.ref, signal);
    presentEntries.push('- ' + info.name + (info.brief ? '：' + info.brief : ''));
  }
  if (presentEntries.length) {
    lines.push('在场角色：');
    for (const entry of presentEntries) lines.push(entry);
  }
  const text = lines.join('\n');
  tsian.trace('read_scene', { ref: input.ref, path: path, presentCount: presentEntries.length, length: text.length });
  return { text: text };
}
return readScene(input, tsian, signal);

{
  "name": "read_relationships",
  "title": "读取关系",
  "description": "输入角色实体 ref（如 character:萧玄），读对应人物关系分片 save/relationships/<scope>.json，格式化为人类可读文本返回（主体名 + 各条角色关系 to/type/note）。供社交场景快速了解角色间关系；非角色关联不应写入 relationships。",
  "parameters": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "ref": {
        "type": "string",
        "description": "主体角色实体 id，格式 <type>:<localId>，如 character:萧玄。"
      }
    },
    "required": [
      "ref"
    ]
  },
  "executor": {
    "type": "browser_script",
    "path": "run.js",
    "timeoutMs": 3000
  }
}

// read_relationships：读 save/relationships/<scope>.json，格式化返回关系边。
function isRecord(value) { return typeof value === 'object' && value !== null && !Array.isArray(value); }
function fail(code, message, details) { const error = new Error(message); error.code = code; if (details !== undefined) error.details = details; throw error; }
function parseRef(ref) {
  if (typeof ref !== 'string' || !ref.trim()) fail('READ_RELATIONSHIPS_INVALID_ARGS', 'ref must be a non-empty string.', { ref: ref });
  const parts = ref.split(':');
  if (parts.length !== 2 || !parts[0] || !parts[1]) fail('READ_RELATIONSHIPS_INVALID_ARGS', 'ref must use <type>:<localId>.', { ref: ref });
  return { type: parts[0], localId: parts[1] };
}
async function readEntityName(tsian, ref, signal) {
  const seg = ref.split(':');
  if (seg.length !== 2 || !seg[0] || !seg[1]) return ref;
  const path = 'save/entities/' + seg[0] + '/' + seg[1] + '.json';
  signal.throwIfAborted();
  const file = await tsian.workspace.read({ scope: 'effective', path: path });
  if (!file || typeof file.content !== 'string') return ref;
  try { const entity = JSON.parse(file.content); return (isRecord(entity) && entity.name) ? entity.name : ref; } catch (e) { return ref; }
}
async function readRelationships(input, tsian, signal) {
  if (!isRecord(input)) fail('READ_RELATIONSHIPS_INVALID_ARGS', 'input must be an object.', { input: input });
  const parsed = parseRef(input.ref);
  const scope = parsed.type + '-' + parsed.localId;
  const path = 'save/relationships/' + scope + '.json';
  signal.throwIfAborted();
  const file = await tsian.workspace.read({ scope: 'effective', path: path });
  if (!file || typeof file.content !== 'string') fail('READ_RELATIONSHIPS_NOT_FOUND', 'Relationship file not found.', { ref: input.ref, path: path });
  let rel;
  try { rel = JSON.parse(file.content); } catch (e) { fail('READ_RELATIONSHIPS_JSON_INVALID', 'Relationship file is not valid JSON.', { path: path }); }
  if (!isRecord(rel)) fail('READ_RELATIONSHIPS_INVALID', 'Relationship must be a JSON object.', { path: path });
  const subjectName = await readEntityName(tsian, rel.subject || input.ref, signal);
  const lines = [];
  lines.push(subjectName + ' 的关系：');
  const edges = Array.isArray(rel.edges) ? rel.edges : [];
  for (const edge of edges) {
    if (!isRecord(edge) || typeof edge.to !== 'string') continue;
    signal.throwIfAborted();
    const toName = await readEntityName(tsian, edge.to, signal);
    const type = edge.type || '';
    const note = typeof edge.note === 'string' && edge.note.trim() ? ' — ' + edge.note : '';
    lines.push('- ' + toName + (type ? '（' + type + '）' : '') + note);
  }
  if (edges.length === 0) lines.push('（无关系记录）');
  const text = lines.join('\n');
  tsian.trace('read_relationships', { ref: input.ref, path: path, edgeCount: edges.length, length: text.length });
  return { text: text };
}
return readRelationships(input, tsian, signal);

